ALTER TABLE public.professionals ADD CONSTRAINT professionals_tenant_key UNIQUE(salon_id,id);
ALTER TABLE public.services ADD CONSTRAINT services_tenant_key UNIQUE(salon_id,id);
ALTER TABLE public.professions ADD CONSTRAINT professions_tenant_key UNIQUE(salon_id,id);
ALTER TABLE public.salon_clients ADD CONSTRAINT clients_tenant_key UNIQUE(salon_id,id);
ALTER TABLE public.supplier_brands ADD CONSTRAINT brands_tenant_key UNIQUE(salon_id,id);
ALTER TABLE public.appointments ADD CONSTRAINT appointments_tenant_key UNIQUE(salon_id,id);
ALTER TABLE public.professionals ADD CONSTRAINT professional_profession_tenant FOREIGN KEY(salon_id,profession_id) REFERENCES public.professions(salon_id,id);
ALTER TABLE public.salon_members ADD CONSTRAINT member_professional_tenant FOREIGN KEY(salon_id,professional_id) REFERENCES public.professionals(salon_id,id);
ALTER TABLE public.supplier_products ADD CONSTRAINT product_brand_tenant FOREIGN KEY(salon_id,brand_id) REFERENCES public.supplier_brands(salon_id,id);
ALTER TABLE public.supplier_orders ADD CONSTRAINT order_brand_tenant FOREIGN KEY(salon_id,brand_id) REFERENCES public.supplier_brands(salon_id,id);
ALTER TABLE public.fila_mensagens_ia ADD CONSTRAINT queue_client_tenant FOREIGN KEY(salon_id,client_id) REFERENCES public.salon_clients(salon_id,id), ADD CONSTRAINT queue_appointment_tenant FOREIGN KEY(salon_id,appointment_id) REFERENCES public.appointments(salon_id,id);
CREATE FUNCTION public.public_support_contact() RETURNS TABLE(whatsapp_master text,email_master text,nome_suporte text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT whatsapp_master,email_master,nome_suporte FROM public.config_suporte_master WHERE id=1 $$;
REVOKE ALL ON FUNCTION public.public_support_contact() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_support_contact() TO anon,authenticated;
CREATE FUNCTION public.protect_referral_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (to_jsonb(new)-ARRAY['status','paid_at']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['status','paid_at']) THEN RAISE EXCEPTION 'Valores da venda são imutáveis'; END IF; IF new.status NOT IN ('pago','pendente_a_pagar','cancelado') THEN RAISE EXCEPTION 'Status inválido'; END IF; RETURN new; END $$;
CREATE TRIGGER referral_snapshot BEFORE UPDATE ON public.referral_sales FOR EACH ROW EXECUTE FUNCTION public.protect_referral_snapshot();
CREATE FUNCTION public.public_salon_identity(_salon uuid) RETURNS TABLE(id uuid,name text,logo_url text,brand_color text,name_article text,nome_agente text,genero text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.id,s.name,s.logo_url,s.brand_color,s.name_article,c.nome_agente,c.genero FROM public.salons s LEFT JOIN public.config_agente_secretario c ON c.salon_id=s.id WHERE s.id=_salon AND s.status='ativo' $$;
REVOKE ALL ON FUNCTION public.public_salon_identity(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_salon_identity(uuid) TO anon,authenticated;
CREATE TABLE public.lead_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), channel text NOT NULL DEFAULT 'web', contact text NOT NULL DEFAULT '', token_hash text NOT NULL, messages jsonb NOT NULL DEFAULT '[]', handoff boolean NOT NULL DEFAULT false, handoff_reason text NOT NULL DEFAULT '', paused_reason text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.lead_conversations TO authenticated; GRANT ALL ON public.lead_conversations TO service_role;
ALTER TABLE public.lead_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY lead_manager_read ON public.lead_conversations FOR SELECT TO authenticated USING(public.manages_salon(salon_id));
CREATE POLICY lead_manager_update ON public.lead_conversations FOR UPDATE TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
ALTER PUBLICATION supabase_realtime ADD TABLE public.lead_conversations;
CREATE TABLE public.whatsapp_webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id text NOT NULL UNIQUE, event text NOT NULL, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, processing_error text NOT NULL DEFAULT '');
GRANT SELECT ON public.whatsapp_webhook_events TO authenticated; GRANT ALL ON public.whatsapp_webhook_events TO service_role;
ALTER TABLE public.whatsapp_webhook_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY webhook_admin_read ON public.whatsapp_webhook_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.whatsapp_outbound (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), conversation_id uuid REFERENCES public.lead_conversations(id), inbound_message_id text UNIQUE, provider_message_id text UNIQUE, body text NOT NULL, recipient text NOT NULL, status text NOT NULL DEFAULT 'pending', error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.whatsapp_outbound TO authenticated; GRANT ALL ON public.whatsapp_outbound TO service_role;
ALTER TABLE public.whatsapp_outbound ENABLE ROW LEVEL SECURITY;
CREATE POLICY outbound_read ON public.whatsapp_outbound FOR SELECT TO authenticated USING(public.manages_salon(salon_id));